{
  "service": "gateway",
  "description": "gateway edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8080
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "shipping",
      "host": "shipping.internal",
      "port": 9486,
      "weight": 5,
      "health_check": "/healthz"
    },
    {
      "name": "orders",
      "host": "orders.internal",
      "port": 8303,
      "weight": 1,
      "health_check": "/healthz"
    },
    {
      "name": "notifications",
      "host": "notifications.internal",
      "port": 8152,
      "weight": 6,
      "health_check": "/healthz"
    },
    {
      "name": "pricing",
      "host": "pricing.internal",
      "port": 9587,
      "weight": 7,
      "health_check": "/healthz"
    },
    {
      "name": "search",
      "host": "search.internal",
      "port": 7136,
      "weight": 5,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/notifications/summary",
      "upstream": "notifications",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 2000,
      "retries": 1
    },
    {
      "path": "/api/v1/orders/quotes",
      "upstream": "orders",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 2500,
      "retries": 0
    },
    {
      "path": "/api/v1/search/refunds",
      "upstream": "search",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 1500,
      "retries": 1
    },
    {
      "path": "/api/v1/pricing/events",
      "upstream": "pricing",
      "methods": [
        "POST"
      ],
      "timeout_ms": 5000,
      "retries": 1
    },
    {
      "path": "/api/v1/search/tokens",
      "upstream": "search",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 2500,
      "retries": 3
    },
    {
      "path": "/api/v1/notifications/status",
      "upstream": "notifications",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 5000,
      "retries": 1
    },
    {
      "path": "/api/v1/orders/tokens",
      "upstream": "orders",
      "methods": [
        "GET"
      ],
      "timeout_ms": 1000,
      "retries": 3
    },
    {
      "path": "/api/v1/orders/history",
      "upstream": "orders",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 5000,
      "retries": 2
    },
    {
      "path": "/api/v1/orders/refunds",
      "upstream": "orders",
      "methods": [
        "GET"
      ],
      "timeout_ms": 3000,
      "retries": 0
    }
  ]
}

